// Generated by scripts/build-glossary-data.mjs from content-source/glossary. Do not edit by hand.
export const GLOSSARY_SHARD = Object.freeze({"circulating-supply":{"slug":"circulating-supply","cat":"basics","en":"Circulating supply","contentLocale":"zh-Hans","term":"流通量（Circulating Supply）","aka":["流通供应量","Circulating supply","流通盘"],"short":"流通量是指当前已在市场上自由流通、可以被交易的代币数量，不包括仍处于锁仓或尚未发行的部分。","body":["一个代币通常有三个供应数字：最大供应量（协议规定的上限）、总供应量（已经创建出来的数量）和流通量（真正在市场上流动的数量）。团队和投资人锁仓的代币、项目方金库里尚未分配的代币，一般不算进流通量。",["流通量直接决定",["市值","market-capitalization"],"：市值 = 价格 × 流通量。",["代币解锁","token-unlock"],"会增加流通量，",["代币销毁","token-burn"],"会减少流通量。流通量变化快的项目，价格即使不动，市值也会变化。"],["各数据网站对流通量的统计口径可能不同，比如是否计入",["质押","staking"],"中的代币、",["交易所","centralized-exchange"],"储备或基金会持有部分。看到差异时，可以参考项目官方披露和",["链上数据","on-chain-analysis"],"。"]],"example":"假设某代币最大供应量 10 亿枚，已铸造 6 亿枚，其中 2 亿枚锁仓给团队和投资人，1 亿枚在基金会金库，剩余 3 亿枚在市场流通。价格为 1.5 USDT 时，流通市值 = 1.5 × 3 亿 = 4.5 亿 USDT。下个月若解锁 5000 万枚给投资人，流通量升到 3.5 亿枚，增加约 16.7%。","mistakes":["把总供应量当成流通量，用错了数字计算市值。","忽略锁仓代币，以为供应已经固定不变。","只看一个数据网站，不知道各平台统计口径有差别。"],"faq":[{"q":"流通量和总供应量有什么区别？","a":"总供应量是已经创建的全部代币，流通量只是其中能在市场自由交易的部分，锁仓和金库部分不算在内。"},{"q":"流通量增加一定会让价格下跌吗？","a":"不一定，但新增供应需要新的买盘来承接，如果需求没有同步增加，价格就容易承压。"}],"title":"什么是流通量？流通量、总量与最大供应量的区别","description":"流通量（流通供应量）是什么意思？讲清流通量、总供应量和最大供应量的区别，以及代币解锁和销毁如何改变流通量与市值。","related":[["market-capitalization","市值（Market Cap）","市值是一个加密货币的当前价格乘以流通量得到的总价值，用来比较不同币种的规模，英文为 Market Cap。"],["fully-diluted-valuation","完全稀释估值（FDV）","完全稀释估值（FDV）是用当前价格乘以代币最大供应量（或总供应量）算出的估值，表示所有代币都流通后的理论市值。"],["token-unlock","代币解锁（Token Unlock）","代币解锁是指原本锁仓、不能交易的代币按预定时间表释放进入流通，常见于团队、投资人和生态基金的份额。"],["token-burn","代币销毁（Token Burn）","代币销毁是把代币发送到无人掌握私钥的地址或由合约直接注销，使其永久退出流通，从而减少总供应量。"]],"lesson":null,"coin":null,"tool":"/coins","cta":false},"bear-market":{"slug":"bear-market","cat":"basics","en":"Bear market","contentLocale":"zh-Hans","term":"熊市（Bear Market）","aka":["Bear market","熊市行情","币圈寒冬"],"short":"熊市是指加密货币或其他资产价格在较长时间内持续下跌、市场情绪悲观、成交量和关注度明显下降的阶段，与之相对的是牛市。","body":[["熊市里价格不断创出更低的高点和更低的低点，主流币可能从高点回撤一半以上，小",["市值","market-capitalization"],["山寨币","altcoin"],"跌幅往往更大，甚至归零。项目融资变难，部分平台和项目在这个阶段倒闭，币圈常称为“寒冬”。"],["熊市中也会有强劲反弹，称为“熊市反弹”，涨幅可能达到 30% 以上后又继续下跌。很多人把反弹误当成",["牛市","bull-market"],"回归而追高，再次被套。"],["熊市对",["长期持有","hodl"],"者和短线交易者意义不同：有人用",["定投","dollar-cost-averaging"],"在低位慢慢积累，有人用做空或持有",["稳定币","stablecoin"],"来降低风险。无论哪种方式，都要提前想清楚自己能承受多长时间、多大幅度的账面亏损。"]],"example":"假设你在 100 USDT 买入某币，熊市中它跌到 30 USDT，跌幅 70%。很多人没意识到：要从 30 回到 100，需要上涨约 233%。如果你从 100 开始每月定投 100 USDT，分别在 80、60、40、30 USDT 买入，五次共投入 500 USDT，平均成本约为 51 USDT，而不是 100。","mistakes":["把熊市反弹当作新一轮牛市，高位追入。","为了回本在熊市里不断加杠杆抄底。","把资金放在高收益但不透明的平台上，平台在熊市中出问题。"],"faq":[{"q":"熊市应该怎么办？","a":"常见思路是降低杠杆、控制仓位、保留现金或稳定币，并根据自己的周期决定是否定投。没有适用于所有人的固定做法。"},{"q":"熊市的底部怎么判断？","a":"底部通常只能事后确认。市场情绪、链上数据和估值可以作为参考，但都无法准确给出最低点。"}],"title":"什么是熊市？加密货币熊市的含义与应对","description":"熊市是什么意思？讲清加密货币熊市的特征、熊市反弹为什么容易误判、跌 70% 后要涨多少才能回本，以及定投成本怎么算。","related":[["bull-market","牛市（Bull Market）","牛市是指加密货币或其他资产价格在较长时间内持续上涨、成交活跃、市场情绪普遍乐观的阶段，与之相对的是熊市。"],["fud","FUD（恐惧、不确定、怀疑）","FUD 是 Fear、Uncertainty、Doubt 的缩写，指在市场上传播的恐惧、不确定和怀疑情绪或消息，常引发恐慌性抛售。"],["dollar-cost-averaging","定投（DCA）","定投（DCA）是按固定周期、用固定金额买入同一资产的策略，不去猜测高低点，借助分批买入摊平成本、降低一次性买在高位的风险。"],["short-selling","卖空（Short Selling）","卖空是先借入或通过合约卖出自己并不持有的资产，等价格下跌后再买回归还或平仓，从下跌中赚取差价的交易方式。"]],"lesson":null,"coin":null,"tool":"/onchain","cta":false},"leverage":{"slug":"leverage","cat":"derivatives","en":"Leverage","contentLocale":"zh-Hans","term":"杠杆（Leverage）","aka":["杠杆倍数","倍数","leverage"],"short":"杠杆是用较少的保证金控制较大仓位的方式，例如 10 倍杠杆意味着 1,000 USDT 保证金可以开出价值 10,000 USDT 的仓位，盈亏同样按仓位价值计算。","body":[["杠杆倍数 = 仓位价值 ÷ 保证金。倍数越高，同样的价格波动对保证金的影响越大：10 倍杠杆下价格反向变动 10%，理论上保证金就亏光，实际因为",["维持保证金","maintenance-margin"],"要求，会在更小的跌幅处被",["强平","liquidation"],"，也就是爆仓。"],["杠杆本身不决定风险，",["仓位大小","position-sizing"],"和止损才决定。同样开 5,000 ",["USDT","usdt"]," 的仓位，用 5 倍还是 20 倍，价格波动带来的盈亏完全一样，区别是占用的保证金和",["强平价","liquidation-price"],"位置。高杠杆的真正危险是让人很容易开出远超能力的仓位。"],[["交易所","centralized-exchange"],"对不同币种、不同仓位规模设置不同的最高杠杆，仓位越大可用杠杆越低。部分国家和地区对散户可用的杠杆有监管上限，交易所也会根据地区限制产品。"]],"example":"假设你有 1,000 USDT，用 20 倍杠杆开 BTC 多单，仓位价值 20,000 USDT。BTC 上涨 5%，你赚 1,000 USDT，保证金翻倍；但下跌 5% 就亏 1,000 USDT，等于全部保证金，实际在跌到 5% 之前就会被强平。如果只用 2 倍杠杆开 2,000 USDT 仓位，同样下跌 5% 只亏 100 USDT，是保证金的 10%。","mistakes":["用最高杠杆开满仓，价格正常波动 2% 到 3% 就爆仓。","认为降低杠杆就一定安全，却在全仓模式下用全部余额加仓。","只看杠杆倍数，不计算强平价和止损时的实际亏损。"],"faq":[{"q":"新手用几倍杠杆合适？","a":"没有统一标准，关键是先用仓位管理确定每笔可承受的亏损，再看杠杆是否让强平价离开仓价足够远。很多有经验的交易者实际有效杠杆很低。"},{"q":"杠杆越高赚得越多吗？","a":"杠杆放大的是盈亏两个方向，收益和亏损对保证金的比例同步放大，高杠杆也更容易在正常波动中被强平。"}],"title":"杠杆是什么意思？合约杠杆倍数怎么选","description":"解释加密货币合约杠杆的含义和计算方式、杠杆和仓位大小对风险的不同影响，以及高杠杆为什么容易在正常波动中爆仓。","related":[["margin-trading","杠杆交易（Margin Trading）","杠杆交易是用自己的资金作保证金，向交易所借入资金或币来放大买卖规模的交易方式，借款要付利息，亏损到一定程度会被强平。"],["liquidation-price","强平价（Liquidation Price）","强平价是标记价格达到后会触发仓位强制平仓的价格，由开仓价、杠杆倍数、维持保证金率以及保证金模式共同决定。"],["initial-margin","初始保证金（Initial Margin）","初始保证金是开立一笔杠杆或合约仓位时必须冻结的最低资金，等于仓位价值除以杠杆倍数，杠杆越高，所需初始保证金越少。"],["isolated-margin","逐仓保证金（Isolated Margin）","逐仓保证金是一种保证金模式，每个仓位只使用单独分配给它的保证金，仓位被强平时最多亏掉这部分，不会动用账户里的其他资金。"],["position-sizing","仓位管理（Position Sizing）","仓位管理是根据账户总资金、可承受的单笔亏损和止损距离，计算每笔交易应该开多大仓位的方法，目的是让任何一笔交易都不会重伤账户。"]],"lesson":{"id":"E19","slug":"what-leverage-does","ep":19,"title":"10倍杠杆，是钱变多，还是风险变大？"},"coin":null,"tool":"/liquidations","cta":true},"auto-deleveraging":{"slug":"auto-deleveraging","cat":"derivatives","en":"Auto-deleveraging (ADL)","contentLocale":"zh-Hans","term":"自动减仓（ADL）","aka":["ADL","自动减仓机制","auto-deleveraging"],"short":"自动减仓（ADL）是合约交易所在强平仓位无法以足够好的价格平掉、风险保障基金又不足以弥补亏损时，按排名强制减少对手方盈利仓位的风控机制。","body":[["正常情况下，被",["强平","liquidation"],"的仓位由强平引擎在市场上平掉，穿仓损失由",["风险保障基金","insurance-fund"],"承担。但在极端行情中，市场深度不够、价格跳空，基金可能不足以覆盖，",["交易所","centralized-exchange"],"就会启动 ADL：找到方向相反、盈利较多、",["杠杆","leverage"],"较高的仓位，按破产价格把它们部分或全部平掉。"],"被 ADL 的人并不是亏钱，而是盈利仓位被提前结束，失去了后续继续盈利的机会。排名一般综合盈利比例和有效杠杆，很多交易所在仓位旁用几格指示灯显示你在 ADL 队列中的位置，灯越亮越靠前。","ADL 很少发生，但在剧烈行情、小币合约或深度较差的市场里更常见。降低杠杆、适时止盈部分仓位，可以降低在队列中的排名。"],"example":["假设一位交易者持有 5 ",["BTC","bitcoin"]," 的空单，被强平时的破产价格是 61,000 ",["USDT","usdt"],"，但市场剧烈拉升，强平引擎最快只能在 61,800 买回。每 BTC 缺口 800 USDT，共 4,000 USDT。如果风险保障基金不够覆盖，系统会选中排名最靠前的多单，比如你那张 5 BTC 的高杠杆盈利多单，按 61,000 强制平掉。你保留了到 61,000 为止的盈利，但错过了之后的上涨。"],"mistakes":["以为 ADL 是交易所拿走了自己的利润，其实是按破产价格提前平仓。","长期持有高杠杆高浮盈仓位，不留意 ADL 指示灯的排名。","交易深度很差的小币合约时，没考虑极端行情下更容易触发 ADL。"],"faq":[{"q":"被 ADL 了会亏钱吗？","a":"通常不会产生亏损，你的盈利仓位按破产价格被平掉，已实现的盈利会保留，只是失去了后续盈利的机会。"},{"q":"怎样降低被自动减仓的概率？","a":"降低杠杆、部分止盈以降低盈利比例和有效杠杆，都可以让你在 ADL 队列中的排名靠后。"}],"title":"自动减仓（ADL）是什么？合约 ADL 机制详解","description":"解释合约交易中自动减仓（ADL）在什么情况下触发、如何选择被减仓的盈利仓位，以及怎样通过降低杠杆减少被 ADL 的可能。","related":[["insurance-fund","风险保障基金（Insurance Fund）","风险保障基金是合约交易所设立的资金池，用来弥补被强平仓位以差于破产价格成交时产生的穿仓损失，避免盈利方的收益受到影响。"],["liquidation","强平（Liquidation）","强平（俗称爆仓）是指杠杆或合约仓位的保证金因亏损低于维持保证金要求时，交易所系统自动强制平掉该仓位，以防亏损超过保证金。"],["unrealized-pnl","未实现盈亏（Unrealized PnL）","未实现盈亏是仓位尚未平仓时，按当前价格（合约中通常是标记价格）计算出的账面盈利或亏损，只有平仓后才变成已实现盈亏。"],["leverage","杠杆（Leverage）","杠杆是用较少的保证金控制较大仓位的方式，例如 10 倍杠杆意味着 1,000 USDT 保证金可以开出价值 10,000 USDT 的仓位，盈亏同样按仓位价值计算。"]],"lesson":{"id":"E23","slug":"liquidation-mark-price","ep":23,"title":"爆仓：谁按下了强制平仓按钮？"},"coin":null,"tool":"/liquidations","cta":false},"crypto-wallet":{"slug":"crypto-wallet","cat":"wallets-security","en":"Crypto wallet","contentLocale":"zh-Hans","term":"加密钱包（Crypto Wallet）","aka":["数字钱包","钱包","crypto wallet"],"short":"加密钱包是用来保管私钥、查看余额并签名发送交易的工具，币本身记录在区块链上，钱包保管的是控制这些币的密钥。","body":[["钱包分为",["托管钱包","custodial-wallet"],"和",["非托管钱包","non-custodial-wallet"],"。",["交易所","centralized-exchange"],"账户属于托管钱包，",["私钥","private-key"],"由平台保管；MetaMask、OKX Wallet、Trust Wallet 这类自托管钱包和",["硬件钱包","hardware-wallet"],"，私钥由你自己掌握，通常以 12 或 24 个单词的",["助记词","seed-phrase"],"备份。"],"按联网状态还可以分为热钱包和冷钱包：手机或浏览器插件钱包联网使用，方便但更容易受到钓鱼和恶意软件攻击；硬件钱包等冷钱包把私钥保存在离线设备里，适合长期存放较大金额。","使用钱包最重要的三件事：助记词离线保存、不对任何人透露；转账前核对地址和网络，同一种币在不同链上的地址和网络不能混用；不随便授权陌生合约，定期检查并撤销不需要的授权。"],"example":"假设你要把交易所里的 1,000 USDT 提到自己的钱包。你先确认钱包和交易所都支持同一条网络，例如 TRC20 或 ERC20，然后复制钱包地址，核对开头和结尾几位字符。稳妥做法是先提 10 USDT 测试，到账后再提剩下的 990 USDT。两条网络的提币手续费可能差好几倍，选错网络则可能无法到账。","mistakes":["把助记词截图存在手机相册或云盘里。","提币时选错网络，币发到了钱包不支持的链上。","在钓鱼网站上连接钱包并签名授权，导致资产被转走。"],"faq":[{"q":"加密钱包里真的存着币吗？","a":"没有。币的记录在区块链上，钱包保存的是私钥，用来证明你对这些币的控制权并签名转账。"},{"q":"交易所账户算钱包吗？","a":"算托管钱包，私钥由交易所保管，你使用的是平台的账户余额。自托管钱包则由你自己保管私钥和助记词。"}],"title":"加密钱包是什么？数字货币钱包类型入门","description":"解释加密钱包的本质是保管私钥，介绍托管与非托管、热钱包与冷钱包的区别，以及转账时核对地址和网络的安全要点。","related":[["custodial-wallet","托管钱包（Custodial Wallet）","托管钱包是由交易所或其他第三方代为保管私钥的钱包，你通过账户密码登录使用，资产实际由平台控制，便捷但要承担平台风险。"],["non-custodial-wallet","非托管钱包（自托管钱包）","非托管钱包是由你自己保管私钥或助记词的钱包，资产的控制权完全在你手里，没有任何平台能替你冻结、挪用或找回。"],["seed-phrase","助记词（Seed Phrase）","助记词是由 12 或 24 个英文单词组成的钱包备份，可以推导出钱包里的全部私钥，谁拿到助记词，谁就能控制这个钱包里的所有资产。"],["wallet-address","钱包地址（Wallet Address）","钱包地址是区块链上用于收款的一串字符，相当于你的收款账号，由公钥计算得出，可以公开给别人，但不同链的地址格式不同。"],["hardware-wallet","硬件钱包（Hardware Wallet）","硬件钱包是一种专门保管私钥的小型实体设备，私钥在设备内部生成并签名，从不传到电脑或手机上，是最常用的冷钱包形式。"]],"lesson":{"id":"E03","slug":"exchange-vs-wallet","ep":3,"title":"币到底在哪：交易所和钱包有什么不同？"},"coin":null,"tool":null,"cta":false},"memo-tag":{"slug":"memo-tag","cat":"wallets-security","en":"Memo / destination tag","contentLocale":"zh-Hans","term":"Memo / 标签（Destination Tag）","aka":["Memo","Tag","备注","Destination Tag"],"short":"Memo（也叫标签、Tag）是部分区块链转账时附带的一段数字或文字，交易所靠它识别充值属于哪个用户，充值时漏填或填错就可能无法自动到账。","body":[["XRP、XLM、EOS、TON、ATOM 等一些链上，",["交易所","centralized-exchange"],"常常让所有用户共用同一个",["充币地址","wallet-address"],"，再用 Memo 或 Destination Tag 来区分是谁的钱。所以这类币的充币页面会同时给出“地址”和“Memo/标签”两项。"],"如果你从另一家交易所提币到这里，就必须把两项都填上。漏填 Memo 时，币确实到了交易所的地址，但系统不知道该入哪个账户，通常需要提交工单人工找回，耗时较长，有的平台还会收费。","如果是转到自己的个人钱包，往往不需要 Memo；但充到交易所或某些托管服务时，以对方页面的要求为准，不要凭经验省略。"],"example":"假设你要把 500 XRP 充到某交易所，充币页面显示地址 rEb8……Zx9 和标签 104857632。你在提币页面填好地址，却把标签填成了 10485763，少了最后一位数字。链上转账成功，但交易所无法匹配到你的账户，这 500 XRP 只能通过客服人工处理。提交前把 9 位标签逐位核对一遍，就能避免这种情况。","mistakes":["只复制了地址，忘了填写 Memo 或标签。","把 Memo 填到了地址栏，或者把别人的标签抄了过来。","以为所有币都要 Memo，在不需要的网络上随便填了内容导致疑惑。"],"faq":[{"q":"Memo 忘填了还能找回吗？","a":"多数交易所支持人工找回，你需要提供交易哈希、金额和账户信息。是否支持、处理多久以及是否收费，取决于具体平台。"},{"q":"所有币都需要填 Memo 吗？","a":"不是。比特币、以太坊和 ERC20 代币通常不需要，只有部分采用共用地址方案的链和平台需要，以充币页面提示为准。"}],"title":"Memo 是什么？充币标签和 Destination Tag 的作用","description":"充币时的 Memo、标签、Destination Tag 是什么？了解哪些币需要填写、漏填或填错会怎样，以及如何申请找回未到账的资产。","related":[["wallet-address","钱包地址（Wallet Address）","钱包地址是区块链上用于收款的一串字符，相当于你的收款账号，由公钥计算得出，可以公开给别人，但不同链的地址格式不同。"],["blockchain-network","充提币网络（链的选择）","充提币网络是指充币或提币时选择的区块链，例如 USDT 可以走 TRC20、ERC20 或 BEP20 等不同网络，发送方和接收方必须选择同一条链。"],["transaction-hash","交易哈希（TxID）","交易哈希（TxID）是每笔链上交易独一无二的编号，由交易数据计算得出，用它可以在区块浏览器里查到这笔转账的状态、金额和确认数。"]],"lesson":{"id":"E09","slug":"pre-transfer-checklist","ep":9,"title":"转账之前，这几项一个也别猜"},"coin":null,"tool":null,"cta":false},"two-factor-authentication":{"slug":"two-factor-authentication","cat":"wallets-security","en":"Two-factor authentication (2FA)","contentLocale":"zh-Hans","term":"双重验证（2FA）","aka":["2FA","双重认证","二次验证","谷歌验证器"],"short":"双重验证（2FA）是在密码之外再加一道验证的登录与操作保护，常见形式有验证器 App 动态码、短信验证码和硬件安全密钥。","body":["只靠密码，一旦密码泄露账户就失守。开启 2FA 后，登录、提现、修改安全设置时还需要输入第二个因素，例如 Google Authenticator 等验证器 App 每 30 秒刷新一次的 6 位动态码，或者插入 USB/NFC 安全密钥。",["不同方式安全性不同：短信验证码可能被 SIM 卡劫持（补卡攻击）截获，验证器 App 更稳妥，硬件安全密钥（支持 Passkey/FIDO2）对",["钓鱼网站","phishing"],"的防御最好。大部分",["交易所","centralized-exchange"],"支持多种方式并存。"],"开启验证器时生成的密钥或二维码要离线备份。换手机前先迁移，否则旧手机丢失后只能走交易所的人工重置流程，期间提现往往会被临时限制。"],"example":"假设你的交易所密码在一次第三方网站数据泄露中被曝光，攻击者用它尝试登录你的账户。因为你开启了验证器 App，他还需要那 6 位、每 30 秒变化一次的动态码，随机猜中的概率只有百万分之一。登录失败后你收到了异地登录提醒，立刻修改密码，资产没有受到影响。","mistakes":["只开短信验证，没有开启验证器 App 或安全密钥。","把验证器密钥截图存在同一部手机的相册里，手机丢了两样一起丢。","在钓鱼网站上照样输入了 2FA 动态码，以为有 2FA 就不会被盗。"],"faq":[{"q":"2FA 用短信还是谷歌验证器好？","a":"一般建议使用验证器 App 或硬件安全密钥。短信方便，但存在补卡和拦截风险，适合作为补充而不是唯一手段。"},{"q":"换手机了谷歌验证器怎么办？","a":"最好在换机前用备份密钥或 App 的迁移功能把账户转过去。旧手机已经丢失的话，需要通过交易所的身份核验流程重置 2FA。"}],"title":"什么是 2FA 双重验证？交易所账户怎么设置","description":"2FA 双重验证是什么？比较短信、谷歌验证器和硬件安全密钥的安全性，教你备份验证器密钥，避开开启 2FA 后仍被盗的常见情况。","related":[["anti-phishing-code","防钓鱼码（Anti-phishing Code）","防钓鱼码是你在交易所设置的一段自定义文字，之后平台发来的官方邮件里都会带上它，用来帮你分辨真假邮件，识别冒充交易所的钓鱼信息。"],["withdrawal-whitelist","提币白名单（Withdrawal Whitelist）","提币白名单是交易所的一项安全设置，开启后账户只能向你事先登记并验证过的地址提币，即使账户被盗，对方也难以把资产转到陌生地址。"],["phishing","钓鱼攻击（Phishing）","钓鱼攻击是指诈骗者冒充交易所、钱包或项目方，通过假网站、假邮件、假客服诱导你交出密码、验证码、助记词或签下恶意授权，从而盗取资产。"],["sub-account","子账户（Sub-account）","子账户是在同一个交易所主账户下开设的独立交易账户，资产和仓位彼此隔离，可以分别用于不同策略、API机器人或资金用途，并由主账户统一管理。"]],"lesson":{"id":"E04","slug":"find-the-official-exchange","ep":4,"title":"先认门，再注册：别把账户开在假平台"},"coin":null,"tool":null,"cta":false},"withdrawal-whitelist":{"slug":"withdrawal-whitelist","cat":"wallets-security","en":"Withdrawal whitelist","contentLocale":"zh-Hans","term":"提币白名单（Withdrawal Whitelist）","aka":["提币白名单","提现白名单","地址白名单"],"short":"提币白名单是交易所的一项安全设置，开启后账户只能向你事先登记并验证过的地址提币，即使账户被盗，对方也难以把资产转到陌生地址。","body":[["开启白名单后，你需要先在地址簿中添加常用地址，并通过邮箱、",["2FA","two-factor-authentication"]," 等验证。之后每次提币只能选择名单中的地址，新增地址往往还要等待一段冷静期，比如 24 小时，具体时长以平台规定为准。"],"它的意义在于给盗号者加一道门槛：即使对方拿到了密码和验证码，也需要先添加新地址并熬过等待期，你有机会在收到通知后冻结账户。它也能减少手动粘贴出错和剪贴板被篡改的风险。","白名单不能防住所有问题，如果你登记的地址本身就是骗子提供的或被投毒的相似地址，白名单只会让错误更“顺利”。添加地址时务必逐位核对。"],"example":["假设你的账户里有 5,000 ",["USDT","usdt"],"，已开启提币白名单，名单里只有自己的",["硬件钱包","hardware-wallet"],"地址。某天有人盗取了你的密码和短信验证码，尝试把资金提到新地址，系统要求先添加地址并等待 24 小时。你在 5 分钟后收到“新增地址”邮件，立即冻结账户，5,000 USDT 一分没少。"],"mistakes":["嫌麻烦不开白名单，账户被盗后资产几分钟内就被提空。","从聊天记录里复制地址加入白名单，没有向本人当面确认。","开启白名单的同时关闭了新增地址的等待期，削弱了保护效果。"],"faq":[{"q":"开了提币白名单还能转给别人吗？","a":"可以，但要先把对方地址添加进白名单并完成验证，部分平台还需等待一段时间才能使用。"},{"q":"白名单地址填错了怎么办？","a":"可以在地址簿里删除或修改。修改通常也要重新验证，提币前请再次核对地址和网络。"}],"title":"什么是提币白名单？作用和设置方法","description":"提币白名单是什么？了解交易所地址白名单如何防止盗号后资产被转走、新增地址等待期的意义，以及添加白名单地址时的注意事项。","related":[["wallet-address","钱包地址（Wallet Address）","钱包地址是区块链上用于收款的一串字符，相当于你的收款账号，由公钥计算得出，可以公开给别人，但不同链的地址格式不同。"],["two-factor-authentication","双重验证（2FA）","双重验证（2FA）是在密码之外再加一道验证的登录与操作保护，常见形式有验证器 App 动态码、短信验证码和硬件安全密钥。"],["address-poisoning","地址投毒（Address Poisoning）","地址投毒是一种诈骗手法，骗子生成一个首尾字符与你常用地址相同的假地址，向你发送小额或零额转账，让它混进你的交易记录，等你复制错地址。"],["anti-phishing-code","防钓鱼码（Anti-phishing Code）","防钓鱼码是你在交易所设置的一段自定义文字，之后平台发来的官方邮件里都会带上它，用来帮你分辨真假邮件，识别冒充交易所的钓鱼信息。"]],"lesson":{"id":"E09","slug":"pre-transfer-checklist","ep":9,"title":"转账之前，这几项一个也别猜"},"coin":null,"tool":null,"cta":false},"crypto-backed-stablecoin":{"slug":"crypto-backed-stablecoin","cat":"stablecoins","en":"Crypto-backed stablecoin","contentLocale":"zh-Hans","term":"加密资产抵押型稳定币（Crypto-backed stablecoin）","aka":["加密抵押稳定币","超额抵押稳定币","去中心化稳定币"],"short":"加密资产抵押型稳定币是用户把ETH等加密资产超额抵押进智能合约后铸造出来的稳定币，DAI是最典型的例子，抵押品不足时仓位会被清算。","body":[["与USDT、USDC这类由公司用现金和国债做储备的法币抵押型",["稳定币","stablecoin"],"不同，加密抵押型稳定币的储备就在链上，任何人都可以通过",["区块浏览器","block-explorer"],"查看抵押品数量。用户存入抵押品，按协议规定的最低抵押率借出（铸造）稳定币，还款时把稳定币销毁，再取回抵押品。"],"因为ETH等抵押品波动很大，协议要求超额抵押，比如价值150美元的抵押品只能铸造100美元稳定币。当抵押品价格下跌、抵押率跌破清算线时，协议会自动拍卖或出售抵押品偿还债务，借款人还要承担清算罚金。","这种设计的好处是透明、无需信任单一发行方；缺点是资金效率低，而且在极端行情下，抵押品被集中清算可能造成连锁抛售。不同协议的抵押率、清算罚金和可用抵押品种类各不相同，使用前要看清参数。"],"example":"假设某金库要求最低抵押率150%。ETH价格为3,000美元，你存入5个ETH，抵押价值15,000美元，最多可以铸造10,000枚稳定币。如果ETH跌到2,700美元，抵押价值变成13,500美元，抵押率只有135%，低于150%，你的仓位就会被清算。为留出缓冲，你只铸造6,000枚，此时抵押率为250%，ETH要跌到1,800美元才会触发清算线。","mistakes":["按最低抵押率借满，稍有回调就被清算并支付罚金。","以为稳定币是“去中心化”的就没有风险，忽视了抵押品暴跌和预言机故障的可能。","只盯着借出的稳定币，忘了抵押品价格需要持续监控和及时补仓。"],"faq":[{"q":"DAI和USDT有什么区别？","a":"USDT由Tether公司以现金、国债等资产作储备，属于中心化发行；DAI主要由用户在链上超额抵押加密资产铸造，储备公开透明，但会受抵押品价格波动影响。"},{"q":"为什么加密抵押型稳定币要超额抵押？","a":"因为抵押品价格波动大，超额部分是安全垫，保证抵押品价值下跌一段后仍能覆盖已铸造的稳定币。"}],"title":"什么是加密资产抵押型稳定币？DAI式超额抵押详解","description":"讲清加密资产抵押型稳定币的铸造、超额抵押和清算机制，用具体数字说明抵押率怎么算，以及和USDT、USDC的区别。","related":[["stablecoin","稳定币（Stablecoin）","稳定币是一种设计为与美元等法币或资产保持稳定兑换比例的加密货币，最常见的是 1 枚兑 1 美元的 USDT 和 USDC，是加密交易中的主要计价和结算工具。"],["defi-lending","DeFi 借贷","DeFi 借贷是通过智能合约进行的超额抵押借贷，存款人把资产存入资金池赚利息，借款人先存入抵押品再借出其他资产，抵押不足时会被自动清算。"],["liquidation","强平（Liquidation）","强平（俗称爆仓）是指杠杆或合约仓位的保证金因亏损低于维持保证金要求时，交易所系统自动强制平掉该仓位，以防亏损超过保证金。"],["algorithmic-stablecoin","算法稳定币（Algorithmic stablecoin）","算法稳定币是主要依靠代码规则调节供应量、而不是靠足额现金或抵押品来维持1美元价格的稳定币，在信心崩溃时容易出现严重脱锚。"]],"lesson":null,"coin":{"slug":"dai","name":"Dai","symbol":"DAI"},"tool":null,"cta":false},"block-explorer":{"slug":"block-explorer","cat":"onchain","en":"Block explorer","contentLocale":"zh-Hans","term":"区块浏览器（Block explorer）","aka":["区块链浏览器","Block explorer","链上浏览器"],"short":"区块浏览器是一种可以按交易哈希、钱包地址或区块高度查询区块链上公开记录的网站或工具，例如以太坊的Etherscan和波场的Tronscan。","body":[[["区块链","blockchain"],"本身是一份公开账本，但普通人无法直接读取原始数据。区块浏览器把这些数据整理成可读的页面：输入",["交易哈希（TxID）","transaction-hash"],"就能看到这笔转账的发送方、接收方、金额、手续费、所在区块和",["确认数","block-confirmations"],"；输入地址则能看到它的余额和历史记录。"],["每条链都有自己的浏览器。",["比特币","bitcoin"],"、",["以太坊","ethereum"],"、BNB Chain、波场、Solana等链的浏览器互不通用，查一笔TRC20转账要去波场浏览器，查ERC20转账要去以太坊浏览器。在错误的浏览器里搜索，会显示找不到交易。"],"提币或充币没到账时，区块浏览器是第一个排查工具：交易显示成功且确认数足够，说明资金已经到了目标地址，问题多半出在接收平台的入账流程；交易仍在等待或失败，则需要回到发送方处理。"],"example":["假设你从",["交易所","centralized-exchange"],"A向交易所B提了1,000 USDT，选择TRC20网络，提币记录里给出了一串交易哈希。你把它粘贴到波场浏览器，看到状态为成功、已获得25个确认、接收地址与你在B复制的充值地址完全一致、金额为1,000 USDT。这说明链上转账已完成，B迟迟未入账时，你应该带着这串哈希联系B的客服，而不是找A。"],"mistakes":["在错误的链的浏览器里查询，误以为交易不存在。","只看到“成功”就不核对接收地址和金额，忽视了地址填错的可能。","访问搜索结果里的仿冒浏览器网站，并在上面连接钱包或签名。"],"faq":[{"q":"区块浏览器上查不到我的交易怎么办？","a":"先确认用的是正确链的浏览器，再确认交易哈希没有复制错。如果发送方还没广播交易，浏览器上也不会出现记录。"},{"q":"别人能通过区块浏览器看到我的余额吗？","a":"能看到某个地址的余额和交易记录，但浏览器本身不显示地址背后是谁。不过一旦地址与你的身份关联，所有记录都可以追溯。"}],"title":"什么是区块浏览器？如何用交易哈希查询转账","description":"区块浏览器是什么？学会用交易哈希和钱包地址查询转账状态、确认数和手续费，快速排查充币、提币迟迟未到账的问题。","related":[["transaction-hash","交易哈希（TxID）","交易哈希（TxID）是每笔链上交易独一无二的编号，由交易数据计算得出，用它可以在区块浏览器里查到这笔转账的状态、金额和确认数。"],["block-confirmations","区块确认数（Confirmations）","区块确认数是指一笔交易被打包进区块后，其后又新增了多少个区块，确认数越多，交易被回滚的可能性越小，交易所据此决定何时为你入账。"],["wallet-address","钱包地址（Wallet Address）","钱包地址是区块链上用于收款的一串字符，相当于你的收款账号，由公钥计算得出，可以公开给别人，但不同链的地址格式不同。"],["on-chain-analysis","链上分析（On-chain analysis）","链上分析是通过研究区块链上公开记录的转账、地址余额、交易所资金流向等数据，来判断市场参与者行为和资金动向的分析方法。"]],"lesson":{"id":"E10","slug":"transfer-not-arrived","ep":10,"title":"显示成功却没到账，该查哪里？"},"coin":null,"tool":null,"cta":false},"travel-rule":{"slug":"travel-rule","cat":"regulation","en":"Travel rule","contentLocale":"zh-Hans","term":"旅行规则（Travel Rule）","aka":["Travel Rule","转账信息规则","FATF第16条建议"],"short":"旅行规则是FATF第16条建议对虚拟资产服务商的要求：在转账时收集并传递汇款方和收款方的身份信息，让资金和信息一起“旅行”。","body":[["这条规则最早用于银行电汇，后来被FATF扩展到加密资产。在FATF的指引中，门槛为1,000美元或欧元，超过门槛的转账需要在",["交易所","centralized-exchange"],"之间传递双方姓名、账户等信息。欧盟更严格，自2024年12月30日起，从第一欧元开始就要适用。"],"对用户来说，最直观的变化是提币时多了几道填写步骤：要选择接收平台、填写收款人姓名；如果提到自己的钱包，需要声明这是自托管地址，有时还要用签名或小额转账证明地址归你所有。充值时，来自其他平台的资金可能也要补充汇款方信息才能入账。","不同国家采用的门槛、信息字段和技术方案不完全相同，交易所之间也要支持同一套信息传递协议。如果两边无法对接，转账可能被延迟或退回，提币前看清平台的提示很重要。"],"example":["假设你在欧盟的交易所A准备向另一家交易所B提1,500 ",["USDT","usdt"],"。因为欧盟从第一欧元起适用旅行规则，A要求你选择接收平台为B，并填写收款人姓名。你填的名字和B账户的实名一致，转账顺利入账。如果你把同样1,500 USDT提到自己的",["硬件钱包","hardware-wallet"],"，A则会要求你声明这是自托管地址，并可能要求你签名一条消息来证明地址属于你。"],"mistakes":["提币时随便选“其他平台”或填写不准确的收款人姓名，导致资金被退回或冻结。","以为金额低于1,000就一定不用填写信息，忽略了欧盟等地区从第一欧元起适用。","把币提到不支持旅行规则对接的平台，入账被长时间卡住。"],"faq":[{"q":"提币到自己的钱包也要遵守旅行规则吗？","a":"许多平台会要求你声明这是自托管钱包，部分地区还要求证明地址归你所有，例如签名验证。具体要求取决于平台所在地的规定。"},{"q":"旅行规则会泄露我的隐私吗？","a":"信息只在受监管的服务商之间传递，用于合规审查，不会写到区块链上公开，但你仍应只向官方渠道提交资料。"}],"title":"什么是旅行规则（Travel Rule）？提币为何要填信息","description":"旅行规则是什么？了解FATF第16条建议的门槛、欧盟从第一欧元起适用的要求，以及提币到交易所或自托管钱包时要填什么。","related":[["kyc","KYC（了解你的客户）","KYC是“了解你的客户”（Know Your Customer）的缩写，指交易所等金融服务机构在开户或提高额度时核实用户真实身份的流程，通常需要证件和人脸识别。"],["aml","AML（反洗钱）","AML是“反洗钱”（Anti-Money Laundering）的缩写，指金融机构和交易所为识别、阻止非法资金进入正规体系而建立的一整套监控、审查和报告制度。"],["vasp","虚拟资产服务提供商（VASP）","VASP是“虚拟资产服务提供商”的缩写，指为他人提供加密资产兑换、转账、托管或发行相关服务的企业，例如中心化交易所和托管钱包服务商。"],["withdrawal-whitelist","提币白名单（Withdrawal Whitelist）","提币白名单是交易所的一项安全设置，开启后账户只能向你事先登记并验证过的地址提币，即使账户被盗，对方也难以把资产转到陌生地址。"]],"lesson":{"id":"E09","slug":"pre-transfer-checklist","ep":9,"title":"转账之前，这几项一个也别猜"},"coin":null,"tool":null,"cta":false},"spot-bitcoin-etf":{"slug":"spot-bitcoin-etf","cat":"regulation","en":"Spot bitcoin ETF","contentLocale":"zh-Hans","term":"比特币现货ETF（Spot bitcoin ETF）","aka":["比特币ETF","现货比特币ETF","BTC现货ETF"],"short":"比特币现货ETF是在证券交易所上市、由基金直接持有真实比特币的交易所交易基金，投资者通过证券账户买卖份额，就能获得跟踪比特币价格的敞口。","body":[["美国的比特币现货ETF于2024年1月开始交易。与早期的",["比特币","bitcoin"],"期货ETF不同，现货ETF的基金会用投资者的资金买入比特币，并交给托管机构保管，份额价格大致跟随比特币价格变动。"],["对习惯股票账户的投资者来说，ETF省去了开",["交易所","centralized-exchange"],"账户、管理",["私钥","private-key"],"和提币的麻烦，还能放进部分退休账户或机构的合规投资组合。代价是每年要支付管理费，只能在证券市场交易时间买卖，也无法把份额提成真正的比特币转到链上使用。"],"ETF资金的申购和赎回会带动基金买卖比特币，因此每日资金净流入、净流出成为市场关注的数据。不同国家和地区是否批准、能否购买现货ETF的规定不同，需以当地证券监管的规则为准。"],"example":["假设你通过证券账户买入某比特币现货ETF，金额10,000美元，假设年管理费率为0.25%。持有一年，比特币价格不变的情况下，管理费约为25美元，你的份额价值约9,975美元。如果你改为在交易所直接买入10,000美元的BTC并提到",["冷钱包","cold-wallet"],"，没有年度管理费，但要支付交易手续费和",["提币费","withdrawal-fee"],"，例如合计约15美元，同时自行承担私钥保管的责任。"],"mistakes":["以为买了ETF就持有比特币本身，可以随时提到钱包里。","只比较价格表现，不看各只ETF的管理费和跟踪误差。","在美股休市时比特币大幅波动，却以为ETF可以像交易所一样24小时交易。"],"faq":[{"q":"比特币现货ETF和期货ETF有什么区别？","a":"现货ETF直接持有比特币，期货ETF持有比特币期货合约，后者需要滚动合约，可能产生额外成本和跟踪偏差。"},{"q":"买比特币ETF还是直接买比特币？","a":"ETF适合希望用证券账户管理、不想自己保管私钥的人；直接持有比特币可以链上转账和自托管。选择取决于你的账户条件和使用需求。"}],"title":"什么是比特币现货ETF？与直接买比特币的区别","description":"比特币现货ETF是什么？了解它如何持有真实比特币、2024年1月在美国上市的背景、管理费成本，以及与直接持币的区别。","related":[["bitcoin","比特币（Bitcoin，BTC）","比特币是 2009 年上线的第一个去中心化加密货币，总量上限 2100 万枚，通过工作量证明挖矿维护网络，代号 BTC。"],["tokenized-stocks","代币化股票（Tokenized stocks）","代币化股票是把上市公司股票的价格和经济权益映射到区块链代币上的产品，通常由发行方托管真实股票并按1:1发行代币，可在交易所或链上交易。"],["custodial-wallet","托管钱包（Custodial Wallet）","托管钱包是由交易所或其他第三方代为保管私钥的钱包，你通过账户密码登录使用，资产实际由平台控制，便捷但要承担平台风险。"],["market-capitalization","市值（Market Cap）","市值是一个加密货币的当前价格乘以流通量得到的总价值，用来比较不同币种的规模，英文为 Market Cap。"]],"lesson":null,"coin":{"slug":"bitcoin","name":"Bitcoin","symbol":"BTC"},"tool":null,"cta":false},"geo-restrictions":{"slug":"geo-restrictions","cat":"regulation","en":"Geo-restrictions (restricted regions)","contentLocale":"zh-Hans","term":"地区限制（Geo-restrictions）","aka":["受限地区","限制地区","地理限制"],"short":"地区限制是指交易所因法律、牌照或制裁要求，禁止或限制某些国家和地区的用户注册、交易特定产品或使用全部服务的规定。","body":[["每家",["交易所","centralized-exchange"],"的用户协议里都有一份受限地区名单。原因各不相同：有的地区要求平台必须本地持牌，有的禁止向散户提供合约等衍生品，有的是因为国际制裁。同一家交易所，可能允许某地用户做现货，却不允许交易",["永续合约","perpetual-futures"],"或使用理财产品。"],"平台会通过KYC证件的国籍和居住地、IP地址、手机号等信息判断你的所在地。一旦被认定为受限地区用户，账户可能被限制为只能平仓和提币，不能开新仓或充值。","使用VPN绕过地区限制违反大多数平台的用户协议，一旦被发现，账户可能被冻结或强制关闭，届时你很难得到平台的支持。更稳妥的做法是在注册前查看用户协议中的受限地区条款，选择明确为你所在地区提供服务的平台。"],"example":["假设你在交易所持有一个永续合约多单，名义价值10,000 ",["USDT","usdt"],"，保证金1,000 USDT，同时有5,000 USDT在",["活期理财","crypto-earn"],"中。你搬家到一个该平台禁止提供衍生品的国家，并更新了居住地信息。平台通知你：30天内只能平仓、赎回和提币，不能开新仓。你需要在期限内安排平掉这笔合约仓位，赎回理财，再把6,000 USDT左右的资金转到在新居住地可用的平台。"],"mistakes":["用VPN在受限地区注册使用，日后提现时被要求认证而无法通过。","以为某平台能用现货，就默认它的合约和理财产品也对你开放。","搬到新国家后不更新资料，也不查看平台对该地区的服务政策。"],"faq":[{"q":"为什么交易所会限制某些地区？","a":"主要是为了遵守当地法律、牌照要求和国际制裁规定，平台在没有许可的地区提供服务可能面临处罚。"},{"q":"账户被判定为受限地区怎么办？","a":"通常平台会给出只能平仓和提币的过渡期。按通知要求尽快处理仓位并提走资产，不要尝试用虚假信息规避。"}],"title":"交易所地区限制是什么？受限地区账户怎么办","description":"交易所为什么有受限地区？了解地区限制的原因、平台如何判断你的所在地、账户被限制后的处理方式，以及使用VPN的风险。","related":[["kyc","KYC（了解你的客户）","KYC是“了解你的客户”（Know Your Customer）的缩写，指交易所等金融服务机构在开户或提高额度时核实用户真实身份的流程，通常需要证件和人脸识别。"],["vasp","虚拟资产服务提供商（VASP）","VASP是“虚拟资产服务提供商”的缩写，指为他人提供加密资产兑换、转账、托管或发行相关服务的企业，例如中心化交易所和托管钱包服务商。"],["no-kyc-exchange","免KYC交易所（No-KYC exchange）","免KYC交易所是指不要求用户提交身份证件即可注册、交易或在一定额度内提币的交易平台，包括部分中心化交易所和链上去中心化交易所（DEX）。"],["centralized-exchange","中心化交易所（CEX）","中心化交易所（CEX）是由公司运营、托管用户资产并撮合买卖订单的加密货币交易平台，如币安、OKX、Bybit、Bitget。"]],"lesson":{"id":"E05","slug":"kyc-who-gets-your-id","ep":5,"title":"KYC怎么做？证件应该交给谁？"},"coin":null,"tool":"/exchanges","cta":false},"delisting":{"slug":"delisting","cat":"exchange-features","en":"Delisting","contentLocale":"zh-Hans","term":"下架（Delisting）","aka":["下币","下线","交易对下架","Delisting"],"short":"下架是指交易所停止某个代币或交易对的交易服务，通常先发布公告、给出停止交易和停止提币的时间，之后用户只能在规定期限内把资产提走或兑换。","body":[[["交易所","centralized-exchange"],"下架代币的常见原因包括：项目方长期不开发、",["流动性","liquidity"],"和",["交易量","trading-volume"],"过低、出现安全事件或违规行为、团队不配合审查，以及监管要求。有时只是下架某个",["交易对","trading-pair"],"，例如移除一个币的某些计价对，而币本身仍可交易。"],"下架流程一般是：发布公告，到期停止交易并撤销所有挂单，同时停止充值，再保留一段时间的提币窗口。合约产品会提前停止开仓并在到期时强制结算。下架消息往往会让价格在短时间内大幅下跌，流动性也迅速变差。",["收到公告后，你可以选择在下架前卖出，或者提到支持该币的钱包或其他交易所。提币窗口关闭后，资产可能被平台按规则转换成",["稳定币","stablecoin"],"，或需要联系客服处理，过程会更加麻烦。"]],"example":["假设你持有20,000枚某代币，下架公告发布前价格为0.05 ",["USDT","usdt"],"，市值1,000 USDT。公告后一小时价格下跌40%到0.03 USDT，市值变成600 USDT。你有两个选择：立即卖出，拿回约600 USDT；或者把币提到另一个仍支持它的平台，提币手续费为500枚，到账19,500枚。若之后那个平台的价格是0.028 USDT，到账的币约值546 USDT。"],"mistakes":["不关注交易所公告，等到提币窗口关闭才发现资产被冻结。","以为下架后价格会反弹，在暴跌中加仓抄底。","把币提到不支持该代币或该网络的钱包或平台。"],"faq":[{"q":"代币被下架后还值钱吗？","a":"代币本身仍然存在于链上，还可以在其他支持它的交易所或DEX交易，但流动性和价格通常会受到明显冲击。"},{"q":"下架后没来得及提币怎么办？","a":"先查看公告中的后续安排，有的平台会自动转换为稳定币，有的需要联系客服申请处理，越早处理越好。"}],"title":"什么是代币下架？交易所下币后如何处理","description":"交易所下架代币是什么意思？了解下币的常见原因、停止交易和提币窗口的时间安排，以及收到下架公告后卖出或提币的选择。","related":[["token-listing","上币（Token listing）","上币是指交易所正式开放某个代币的充值和交易，为它开设现货或合约交易对，让用户可以在平台上买卖，通常会提前发布上币公告和开盘时间。"],["liquidity","流动性（Liquidity）","流动性是指一个资产能否在不明显推动价格的情况下快速买入或卖出，流动性越好，买卖价差越窄、大额成交的滑点越小。"],["withdrawal-fee","提币手续费（Withdrawal fee）","提币手续费是你把加密资产从交易所转出到外部地址时，交易所收取的费用，通常按币种和网络收取固定数量，用于覆盖链上Gas费和平台的处理成本。"],["rug-pull","跑路（Rug Pull）","Rug Pull（跑路、拉地毯）是指项目方在吸引投资者买入后，突然撤走流动性池中的资金、大量抛售手中代币或卷走资金，导致代币价格瞬间归零。"]],"lesson":null,"coin":null,"tool":"/activities","cta":false}});
